/* ════════════════════════════════════════════════════════════════
   intake-docs.js: the documents the seeded requests carry, at the
   length real ones run to. Written as plain text — "# " a title,
   "## " a heading, "> " a line set apart, anything else a paragraph —
   and read into the page's blocks by mxReadText().
   ════════════════════════════════════════════════════════════════ */
