/* the plain text above, read into the blocks the document pane draws */
function mxReadText(text) {
  const esc = (x) => x.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return text.split('\n').map(l => l.trim()).filter(Boolean).map(l =>
    l.startsWith('# ') ? { t: 'h1', v: esc(l.slice(2)) }
    : l.startsWith('## ') ? { t: 'h2', v: esc(l.slice(3)) }
    : l.startsWith('> ') ? { t: 'meta', v: esc(l.slice(2)) }
    : { t: 'p', v: esc(l).replace(/^(\d+\.\d+)\s/, '<b>$1</b> ') });
}

